function u(e,t){let n=t/e,r=Number.isFinite(n)&&n>0?Math.sqrt(n):.5;return Math.min(.9,Math.max(.5,r))}function i(e,t,n){if(!Number.isFinite(e)||!Number.isFinite(t)||e<1||t<1)return null;let r=Math.max(e,t);if(r<=64)return null;let o=Number.isFinite(n)?Math.min(.9,Math.max(.5,n)):.5,a=Math.max(o,64/r);return{width:Math.max(1,Math.round(e*a)),height:Math.max(1,Math.round(t*a))}}function s(e,t){return`Scaled to ${e}\xD7${t} to reach the target size.`}export{u as a,i as b,s as c};
